<?php
defined('_JEXEC') or die;
use Joomla\CMS\HTML\HTMLHelper;
$workflow = $this->workflow;
$probability = static fn($value): string => $value === null ? 'Not available' : number_format((float) $value * 100, 2) . '%';
?>
<section class="dc-detail" id="dc-workflow" aria-labelledby="dc-workflow-title">
  <h3 id="dc-workflow-title">Retained forecast and evaluation workflow</h3>
  <p>Read actual stored model runs, predictions, outcomes and evaluation records for one retained match. Explicit commands below use the existing kernel, durable jobs and evidence store.</p>
  <form method="get" action="index.php" class="dc-match-selector">
    <input type="hidden" name="option" value="com_dragonhydra"><input type="hidden" name="section" value="control">
    <label for="dc-match-id">Retained match identifier</label>
    <input id="dc-match-id" name="match_id" type="text" value="<?= $escape($this->workflowMatchId) ?>" required pattern="[a-f0-9]{64}" maxlength="64" aria-describedby="dc-match-help" autocomplete="off">
    <p class="dc-muted" id="dc-match-help">Open a match from <a href="<?= $escape($route('section=matches')) ?>">Matches and teams</a> and choose “Open retained workflow”, or enter its 64-character identifier.</p>
    <button class="btn btn-outline-primary" type="submit">Read retained history</button>
  </form>
  <?php if ($this->workflowError): ?><div class="dc-notice dc-warning" role="status"><?= $escape($this->workflowError) ?></div>
