  <?php else: $match = $workflow['match']; ?>
    <h4 class="mt-4"><?= $escape($match['home']) ?> — <?= $escape($match['away']) ?></h4>
    <dl><dt>Match</dt><dd class="dc-code"><?= $escape($match['id']) ?></dd><dt>Source / fixture</dt><dd><?= $escape($match['source_id']) ?> / <span class="dc-code"><?= $escape($workflow['fixture_key']) ?></span></dd><dt>Competition / date</dt><dd><?= $escape($match['competition']) ?> / <?= $escape($match['event_date']) ?></dd><dt>Match state</dt><dd><?= $escape($match['status']) ?></dd><dt>History cutoff</dt><dd><?= $escape($workflow['cutoff']) ?></dd><dt>Target evidence</dt><dd class="dc-code"><?= $escape($workflow['target_evidence_id']) ?></dd></dl>
    <div class="dc-stats"><div class="dc-stat"><strong><?= $escape($workflow['counts']['models']) ?></strong><span>Retained model runs</span></div><div class="dc-stat"><strong><?= $escape($workflow['counts']['predictions']) ?></strong><span>Retained predictions</span></div><div class="dc-stat"><strong><?= $escape($workflow['counts']['outcomes']) ?></strong><span>Attached outcomes</span></div><div class="dc-stat"><strong><?= $escape($workflow['counts']['evaluations']) ?></strong><span>Persisted evaluation metrics</span></div></div>
    <div class="dc-grid"><section><h4>Create a prospective forecast</h4><p>Explicitly compute and retain the existing statistical models from eligible evidence. A forecast is a research estimate; it is not a final score or proof of predictive skill.</p>
      <?php if (!$this->canImport): ?><p class="dc-unavailable">This action requires the existing Import and synchronize sports data permission.</p>
      <?php elseif (!$workflow['forecast_available']): ?><p class="dc-unavailable">A prospective forecast is unavailable for this match state. Finished results cannot be turned into historical prospective forecasts.</p>
      <?php else: ?><form method="post" action="<?= $escape($route('task=actions.forecast')) ?>"><input type="hidden" name="match_id" value="<?= $escape($match['id']) ?>"><input type="hidden" name="command_key" value="<?= $escape($this->workflowKeys['forecasts']) ?>"><button class="btn btn-primary" type="submit">Create and retain forecast</button><?= HTMLHelper::_('form.token') ?></form><p class="dc-muted">Repeated submission in this session reuses this command’s idempotency key and its existing job.</p><?php endif; ?>
    </section><section><h4>Evaluate a retained forecast</h4><p>Explicitly attach a real later outcome when eligible, then persist comparable operational evaluation metrics. Without an eligible prediction and later result the outcome remains pending.</p>
      <?php if (!$this->canImport): ?><p class="dc-unavailable">This action requires the existing Import and synchronize sports data permission.</p>
      <?php else: ?><form method="post" action="<?= $escape($route('task=actions.evaluate')) ?>"><input type="hidden" name="match_id" value="<?= $escape($match['id']) ?>"><input type="hidden" name="command_key" value="<?= $escape($this->workflowKeys['evaluations']) ?>"><button class="btn btn-outline-primary" type="submit">Evaluate retained forecast</button><?= HTMLHelper::_('form.token') ?></form><?php endif; ?>
    </section></div>

    <p class="dc-muted">At most 100 retained records per kind are displayed below. Totals include every record returned by the selected-match history.</p>
    <h4 class="mt-4">Persisted model runs and supporting evidence</h4>
