    <?php else: ?><ul class="dc-list"><?php foreach ($workflow['models'] as $model): ?><li><strong><?= $escape($model['model_name']) ?></strong> · <?= $escape($model['model_version']) ?><dl><dt>Model record</dt><dd class="dc-code"><?= $escape($model['record_id']) ?></dd><dt>Command / run</dt><dd class="dc-code"><?= $escape($model['run_id']) ?></dd><dt>Input cutoff</dt><dd><?= $escape($model['data_cutoff']) ?></dd><dt>Generated</dt><dd><?= $escape($model['generated_at'] ?: 'Not recorded') ?></dd><dt>Persisted / usable</dt><dd><?= $escape($model['received_at']) ?> / <?= $escape($model['usable_at']) ?></dd></dl>
      <details><summary>Input evidence (<?= $escape(count($model['input_evidence_ids'])) ?> of <?= $escape($model['input_evidence_count']) ?> shown), uncertainty and adaptation</summary><ul><?php foreach ($model['input_evidence_ids'] as $evidence): ?><li class="dc-code"><?= $escape($evidence) ?></li><?php endforeach; ?></ul><h4>Uncertainty</h4><?php if ($model['uncertainty']): ?><ul><?php foreach ($model['uncertainty'] as $uncertainty): ?><li><?= $escape($uncertainty) ?></li><?php endforeach; ?></ul><?php else: ?><p>Not recorded.</p><?php endif; ?><h4>Adaptation</h4><p><?= $escape($model['adaptation_reason'] ?: 'No blocking reason recorded. This alone does not establish improvement.') ?></p><p>Minimum comparable cases: <?= $escape($model['adaptation_minimum_cases'] ?? 'Not recorded') ?>. Retained evaluation evidence: <?= $escape(count($model['adaptation_evidence_ids'])) ?>.</p><ul><?php foreach ($model['adaptation_evidence_ids'] as $evidence): ?><li class="dc-code"><?= $escape($evidence) ?></li><?php endforeach; ?></ul></details>
    </li><?php endforeach; ?></ul><?php endif; ?>
    <h4 class="mt-4">Persisted predictions</h4>
    <?php if (!$workflow['predictions']): ?><p class="dc-unavailable">No prediction has been retained for this match. No probability is invented here.</p>
    <?php else: ?><div class="dc-table-wrap" tabindex="0" role="region" aria-label="Scrollable retained predictions"><table class="dc-table"><caption>Stored probability fractions shown as percentages; these are research estimates.</caption><thead><tr><th scope="col">Prediction / model record</th><th scope="col">Home</th><th scope="col">Draw</th><th scope="col">Away</th><th scope="col">Prediction time</th></tr></thead><tbody><?php foreach ($workflow['predictions'] as $prediction): ?><tr><th scope="row"><span class="dc-code"><?= $escape($prediction['record_id']) ?></span><small class="dc-code"><?= $escape($prediction['model_run_id']) ?></small></th><td><?= $escape($probability($prediction['probabilities']['home'])) ?></td><td><?= $escape($probability($prediction['probabilities']['draw'])) ?></td><td><?= $escape($probability($prediction['probabilities']['away'])) ?></td><td><?= $escape($prediction['predicted_at'] ?: $prediction['received_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <h4 class="mt-4">Attached outcomes</h4>
    <?php if (!$workflow['outcomes']): ?><p class="dc-unavailable">No eligible later outcome is attached. Operational scoring is pending.</p><?php else: ?><ul class="dc-list"><?php foreach ($workflow['outcomes'] as $outcome): ?><li><strong><?= $escape($outcome['outcome']) ?></strong> · <span class="dc-code"><?= $escape($outcome['record_id']) ?></span><p>Source evidence: <span class="dc-code"><?= $escape($outcome['source_evidence_id']) ?></span></p><p class="dc-muted">Usable at <?= $escape($outcome['usable_at']) ?></p></li><?php endforeach; ?></ul><?php endif; ?>
    <h4 class="mt-4">Persisted operational evaluation</h4>
    <?php if (!$workflow['evaluations']): ?><p class="dc-unavailable">No operational evaluation metrics have been persisted for this match. A completed job or an available historical result does not establish forecast performance.</p><?php else: ?><div class="dc-table-wrap" tabindex="0" role="region" aria-label="Scrollable persisted evaluation metrics"><table class="dc-table"><caption>Existing retained cohort metrics, with their original scope and sample size.</caption><thead><tr><th scope="col">Record / model</th><th scope="col">Metric / loss</th><th scope="col">Sample size</th><th scope="col">Source / competition / period / settlement</th><th scope="col">Evaluation cutoff</th></tr></thead><tbody><?php foreach ($workflow['evaluations'] as $evaluation): ?><tr><th scope="row"><span class="dc-code"><?= $escape($evaluation['record_id']) ?></span><small><?= $escape($evaluation['model']) ?> / <?= $escape($evaluation['model_version']) ?></small></th><td><?= $escape($evaluation['metric']) ?> / <?= $escape($evaluation['loss'] ?? 'Not available') ?></td><td><?= $escape($evaluation['sample_size'] ?? 'Not available') ?></td><td><?= $escape(implode(' / ', $evaluation['scope'])) ?></td><td><?= $escape($evaluation['evaluation_cutoff']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <details class="mt-3"><summary>Evaluation scope and limitations</summary><p>A present-knowledge historical holdout is a separate retrospective diagnostic. It is not an operational score for a forecast recorded before a later result.</p><p>Retrospective diagnostic: <?= $workflow['holdout_available'] ? 'Available through its existing supported diagnostic workflow.' : 'Not requested by this retained-history view.' ?> <?= $escape($workflow['holdout_reason']) ?></p><ul><?php foreach ($workflow['limitations'] as $limitation): ?><li><?= $escape($limitation) ?></li><?php endforeach; ?></ul></details>
  <?php endif; ?>
</section>
